const docomoJp = ['NTT DOCOMO · 日本业务年表', 'https://www.docomo.ne.jp/corporate/about/history/'];

function feature(knownBy, title, fact, modelSignal, source, closingLine) {
  const [sourceTitle, sourceUrl] = source;
  return {
    opening: Object.freeze({ title, text: fact + modelSignal, modelSignal, knownBy, sourceTitle, sourceUrl }),
    closingLine,
  };
}

