function resolveNote(country, year, feature) {
  const period = MARKET_DATA[country][year];
  const measurements = { ...period.returns, ...period.benchmarks };
  const references = [];
  const text = feature.closingLine.replace(/\{(abs:)?([a-zA-Z]+)\}/g, (token, absolute, key) => {
    const value = measurements[key];
    if (!Number.isFinite(value)) throw new Error('缺少锐评所需的市场回报：' + country + year + ' ' + key);
    references.push(key);
    const number = absolute ? Math.abs(value) : value;
    return (number > 0 && !absolute ? '+' : '') + (number * 100).toFixed(1) + '%';
  });
  return Object.freeze({
    opening: feature.opening,
    settlement: Object.freeze({ text, asOf: period.asOf, returnKeys: Object.freeze(references) }),
  });
}

export const ERA_NOTES = Object.freeze(Object.fromEntries(Object.entries({ us, jp }).map(([country, features]) => [
  country,
  Object.freeze(Object.fromEntries(Object.entries(features).map(([year, feature]) => [year, resolveNote(country, year, feature)]))),
])));

export function getEraNote(country, year) {
  if (!Object.hasOwn(ERA_NOTES, country) || !Object.hasOwn(ERA_NOTES[country], year)) {
    throw new RangeError('没有该地区与年份的时代侧记。');
  }
  return ERA_NOTES[country][year];
}
